// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;

import java.util.HashMap;
import java.util.Map;

import org.eclipse.kura.linux.watchdog.WatchdogServiceOptions.WatchdogMode;
import org.junit.Test;

public class WatchdogServiceOptionsTest {

    private final Map<String, Object> properties = new HashMap<>();
    private WatchdogServiceOptions options;

    @Test
    public void defaultsAreUsedWhenNoPropertyIsSet() {
        whenOptionsAreCreated();

        thenDefaultsAreUsed();
    }

    @Test
    public void systemdModeIsParsed() {
        givenProperty("watchdogMode", "systemd");

        whenOptionsAreCreated();

        thenModeIs(WatchdogMode.SYSTEMD);
    }

    @Test
    public void directModeIsParsed() {
        givenProperty("watchdogMode", "direct");

        whenOptionsAreCreated();

        thenModeIs(WatchdogMode.DIRECT);
    }

    @Test
    public void modeIsCaseInsensitive() {
        givenProperty("watchdogMode", "DIRECT");

        whenOptionsAreCreated();

        thenModeIs(WatchdogMode.DIRECT);
    }

    @Test
    public void invalidModeFallsBackToSystemd() {
        givenProperty("watchdogMode", "invalid");

        whenOptionsAreCreated();

        thenModeIs(WatchdogMode.SYSTEMD);
    }

    @Test
    public void optionsWithDifferentModesAreNotEqual() {
        givenProperty("watchdogMode", "systemd");
        final WatchdogServiceOptions systemdOptions = new WatchdogServiceOptions(new HashMap<>(this.properties));
        givenProperty("watchdogMode", "direct");

        whenOptionsAreCreated();

        assertNotEquals(systemdOptions, this.options);
    }

    @Test
    public void optionsWithSameValuesAreEqual() {
        givenProperty("watchdogMode", "direct");
        final WatchdogServiceOptions first = new WatchdogServiceOptions(new HashMap<>(this.properties));

        whenOptionsAreCreated();

        assertEquals(first, this.options);
        assertEquals(first.hashCode(), this.options.hashCode());
    }

    private void givenProperty(String key, Object value) {
        this.properties.put(key, value);
    }

    private void whenOptionsAreCreated() {
        this.options = new WatchdogServiceOptions(this.properties);
    }

    private void thenModeIs(WatchdogMode expectedMode) {
        assertEquals(expectedMode, this.options.getWatchdogMode());
    }

    private void thenDefaultsAreUsed() {
        assertFalse(this.options.isEnabled());
        assertEquals(Integer.valueOf(10000), this.options.getPingInterval());
        assertEquals("/dev/watchdog", this.options.getWatchdogDevice());
        assertEquals("/opt/eclipse/kura/data/kura-reboot-cause", this.options.getRebootCauseFilePath());
        assertFalse(this.options.isFailOnUnavailableDevice());
        assertEquals(WatchdogMode.SYSTEMD, this.options.getWatchdogMode());
    }
}
